entries[23489] = { ["name"] = "Extrem sicherer Transporter: Gadgetzan", ["text"] = "Wirken in 10 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nMithrilbarren (12), Echtsilberumwandler (2), Erdenkern (4), Kugel des Wassers (2), Aquamarin (4), Veredelter Mithrilzylinder\nExtrem sicherer Transporter: Gadgetzan\nWird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst\n(260)\nBenötigt Gnomeningenieur\nBenutzen: Transportiert Euch sicher nach Gadgetzan in Tanaris! Die Betonung liegt auf sicher! Jup, nichts kann Euch jemals passieren, wenn Ihr diese Apparatur benutzt! (4 Std. Abklingzeit)" }
