entries[24654] = { ["name"] = "Blaue Drachenschuppengamaschen", ["text"] = "Wirken in 10 sek.\nReagenzien:\nUnverwüstliches Leder (28), Blaue Drachenschuppe (36), Geschmeidiger unverwüstlicher Balg (2), Runenfaden (2)\nBlaue Drachenschuppengamaschen\nWird beim Anlegen gebunden\nBeine Kette\n351 Rüstung\n+35 Ausdauer\n+15 Intelligenz\n+16 Willenskraft\nHaltbarkeit 100 / 100\n55\n\nBlauer Drachenschuppenpanzer (0/3)\nBlaue Drachenschuppenbrustplatte\nBlaue Drachenschuppengamaschen\nBlaue Drachenschuppenschultern" }
entries[24655] = { ["name"] = "Grüne Drachenschuppenstulpen", ["text"] = "Wirken in 10 sek.\nReagenzien:\nUnverwüstliches Leder (20), Grüne Drachenschuppe (30), Geschmeidiger unverwüstlicher Balg , Runenfaden (2)\nGrüne Drachenschuppenstulpen\nWird beim Anlegen gebunden\nHände Kette\n234 Rüstung\n+17 Ausdauer\n+18 Intelligenz\n+9 Naturwiderstand\nHaltbarkeit 45 / 45\n49\n\nGrüner Drachenschuppenpanzer (0/3)\nGrüne Drachenschuppenbrustplatte\nGrüne Drachenschuppengamaschen\nGrüne Drachenschuppenstulpen" }
entries[24658] = { ["name"] = "Instabile Macht", ["text"] = "Sofort\nErhöht 20 Sek. lang Eure Zaubermacht um ( 89 * 12). Bei jedem Wirken eines Zaubers wird der Bonus um 89 Zaubermacht verringert." }
