entries[24680] = { ["name"] = "Kettenblitzschlag", ["text"] = "150 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 10 Ziele aus und verursacht bei jedem folgenden Ziel immer größeren Naturschaden." }
