entries[24682] = { ["name"] = "Gabelblitzschlag", ["text"] = "150 Mana 30 Meter Reichweite\nSofort\nFügt Gegnern in einem kegelförmigen Bereich vor dem Zaubernden 1157 bis 1343 Naturschaden zu." }
entries[24683] = { ["name"] = "Blitzschlagwolke", ["text"] = "60 Mana 30 Meter Reichweite\nSofort\nLässt eine Blitzschlagwolke entstehen, die 15 Sek. anhält und allen Feinden im ausgewählten Gebiet 463 bis 537 Naturschaden und alle 5 Sek. 875 bis 1125 zusätzlichen Schaden zufügt." }
entries[24684] = { ["name"] = "Kettenbrand", ["text"] = "100 Meter Reichweite\nSofort\nTrifft einen Feind mit einem Antimanablitz, der auf einen anderen in der Nähe befindlichen Feind überspringt. Für jeden vom Blitz verbrauchten Manapunkt erleidet das Ziel 0.5 Schaden. Der Zauber wirkt auf maximal 3 Ziele." }
entries[24685] = { ["name"] = "Erdschock", ["text"] = "20 Meter Reichweite\nSofort\nSchockt einen Gegner mit erschütternder Kraft, verursacht Naturschaden und unterbricht 4 Sek. lang den gewirkten Zauber." }
