entries[24800] = { ["name"] = "Essen", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. 2792 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 20 Stärke." }
