entries[24816] = { ["name"] = "Tödlicher Stoß", ["text"] = "30 Wut Nahkampfreichweite\nSpontanzauber 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin heimtückischer Stoß, der Waffenschaden plus 160 verursacht und das Ziel verwundet, sodass die Wirksamkeit jeglicher Heilung 10 Sek. lang um 50% verringert wird." }
entries[24817] = { ["name"] = "Überwältigen", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber 5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nSofortige Überwältigung des Feindes, wodurch Waffenschaden plus 35 entsteht. Kann nur verwendet werden, nachdem das Ziel ausgewichen ist. Auf 'Überwältigen' kann nicht mit Blocken, Ausweichen oder Parieren reagiert werden." }
entries[24818] = { ["name"] = "Giftiger Atem", ["text"] = "Sofort\nVerursacht alle 3 Sek. 350 bis 450 Schaden.\nAbklingzeit um 10 Sek. erhöht." }
entries[24819] = { ["name"] = "Blitzschlagwelle", ["text"] = "100 Meter Reichweite\nSofort\nTrifft einen Feind mit einem Blitzschlag, der auf einen in der Nähe befindlichen Feind überspringt. Der Zauber wirkt sich auf bis zu 10 Ziele aus und verursacht bei jedem folgenden Ziel immer größeren Naturschaden." }
